$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'lib/identity/normalize-business.ps1')
function Assert-Equal { param($Actual,$Expected,[string]$Message); if ($Actual -cne $Expected) { throw "$Message (expected: $Expected, actual: $Actual)" } }
function Assert-True { param([bool]$Condition,[string]$Message); if (-not $Condition) { throw $Message } }

$name = Get-NormalizedNameParts -OriginalName ' 레드폴바버샵 강남신사점 ' -LocalityHints @('강남','신사')
Assert-Equal $name.NormalizedName '레드폴바버샵강남신사점' 'Comparison form is deterministic'
Assert-Equal $name.BaseName '레드폴바버샵' 'Base is source-like for B'
Assert-Equal $name.BranchName '강남신사점' 'Proved locality branch is retained'
$parenthesized=Get-NormalizedNameParts -OriginalName '만복국수(철산점)'; Assert-Equal $parenthesized.BaseName '만복국수' 'Explicit parenthesized branch splits'; Assert-Equal $parenthesized.BranchName '철산점' 'Parenthesized branch remains source-like'
$negative = Get-NormalizedNameParts -OriginalName '테스트 전문점'
Assert-Equal $negative.BaseName '테스트 전문점' 'Generic type is not stripped'; Assert-Equal $negative.BranchName '' 'Generic type is not branch evidence'
$parenthesizedGeneric=Get-NormalizedNameParts -OriginalName '테스트(전문점)'; Assert-Equal $parenthesizedGeneric.BaseName '테스트(전문점)' 'Generic parenthesized type is not stripped'; Assert-Equal $parenthesizedGeneric.BranchName '' 'Generic parenthesized type is not branch evidence'
$suwon=Get-AdministrativeAddressParts '경기도 수원시 권선구'; Assert-Equal $suwon.City '수원시' 'City parsing'; Assert-Equal $suwon.District '권선구' 'District parsing'
$gap=Get-AdministrativeAddressParts '경기도 가평군 가평읍'; Assert-Equal $gap.City '' 'County is not city'; Assert-Equal $gap.District '가평군' 'County district'; Assert-Equal $gap.Dong '가평읍' 'Eup dong'
$seoul=Get-AdministrativeAddressParts '서울특별시 강남구'; Assert-Equal $seoul.Province '서울특별시' 'Province parsing'; Assert-Equal $seoul.City '' 'Province is not city evidence'
$gwangju=Get-AdministrativeAddressParts '경기도 광주시'; Assert-Equal $gwangju.Province '경기도' 'Gyeonggi province is retained'; Assert-Equal $gwangju.City '광주시' 'Gyeonggi Gwangju is not metropolitan Gwangju'
$inHair=Get-NormalizedAddressParts '경기도 동두천시 삼육사로902, 2동 104호(생연동)' '' '경기도' '동두천시'; Assert-Equal $inHair.Province '경기도' 'Canonical row 136 province'; Assert-Equal $inHair.City '동두천시' 'Canonical row 136 city'; Assert-Equal $inHair.Dong '생연동' 'Numeric building dong is not locality'; Assert-Equal $inHair.RoadName '삼육사로' 'No-space road'; Assert-Equal $inHair.BuildingMain '902' 'No-space building'; Assert-Equal $inHair.BuildingSub '' '208동 style token is not building sub'; Assert-Equal $inHair.Unit '104' 'Unit'
$sculls=Get-NormalizedAddressParts '경기도 시흥시 서울대학로264번길 12, 208동 1층 B-112호' '' '경기도' '시흥시'; Assert-Equal $sculls.Province '경기도' 'Canonical row 308 province'; Assert-Equal $sculls.City '시흥시' 'Canonical row 308 city'; Assert-Equal $sculls.Dong '' 'Numeric building dong is not locality'; Assert-Equal $sculls.RoadName '서울대학로264번길' 'Numeric road'; Assert-Equal $sculls.BuildingMain '12' 'Building'; Assert-Equal $sculls.Floor '1' 'Floor'; Assert-Equal $sculls.Unit 'B-112' 'Alpha unit'
$retailDong=Get-NormalizedAddressParts '경기도 동두천시 거북마루로45, 상가동 202호(생연동)' '' '경기도' '동두천시'; Assert-Equal $retailDong.Dong '생연동' 'Retail building dong is not locality'
$ordinalDong=Get-NormalizedAddressParts '경기도 동두천시 장고갯로157, 제1동(생연동)' '' '경기도' '동두천시'; Assert-Equal $ordinalDong.Dong '생연동' 'Ordinal building dong is not locality'
$lotDong=Get-AdministrativeAddressParts '경기도 동두천시 생연동 123-4'; Assert-Equal $lotDong.Dong '생연동' 'Lot address locality remains administrative dong'
$bad=Get-NormalizedAddressParts '경기도 수원시 팔달구신풍로23번길63- 21층 (신풍동)' '' '경기도' '수원시'; Assert-Equal $bad.RoadName '신풍로23번길' 'Malformed road'; Assert-Equal $bad.BuildingMain '' 'No guessed building'; Assert-Equal $bad.BuildingSub '' 'No guessed building sub'; Assert-Equal $bad.Floor '' 'No guessed floor'; Assert-Equal $bad.AddressParseStatus 'PARTIAL' 'Malformed number is partial'; Assert-True ($bad.Warnings -contains 'BUILDING_NUMBER_UNCERTAIN') 'Building warning'; Assert-True ($bad.Warnings -contains 'FLOOR_UNIT_UNCERTAIN') 'Floor warning'; Assert-True ($bad.Warnings -contains 'ADDRESS_PARSE_PARTIAL') 'Partial warning'
$gangnam=Get-NormalizedAddressParts '서울특별시 강남구강남대로84길23(역삼동, (한라클래식 지하1층))' '' '서울특별시' '강남구'; Assert-Equal $gangnam.RoadName '강남대로84길' 'Canonical glued numeric road stays intact'; Assert-Equal $gangnam.BuildingMain '23' 'No-space building after numeric road'; Assert-Equal $gangnam.Floor '지하1' 'Canonical basement floor is retained'
$partial=Get-NormalizedAddressParts '경기도 수원시 신풍로23번길' '' '경기도' '수원시'; Assert-Equal $partial.AddressParseStatus 'PARTIAL' 'Road without number is partial'; Assert-Equal $partial.BuildingMain '' 'No building inferred from road digits'
$noLocality=Get-NormalizedAddressParts '테스트로 10' '' '' ''; Assert-Equal $noLocality.AddressParseStatus 'PARTIAL' 'Road without locality is not complete'; Assert-True ($noLocality.Warnings -contains 'ADDRESS_PARSE_PARTIAL') 'Missing locality is warned'
$conflict=Get-NormalizedAddressParts '경기도 수원시 권선구 권선로 10' '' '서울특별시' '강남구'; Assert-Equal $conflict.Province '' 'Conflicting province is not corrected'; Assert-Equal $conflict.District '' 'Conflicting district is not corrected'; Assert-True ($conflict.Warnings -contains 'ADDRESS_PARSE_PARTIAL') 'Conflict remains partial'
$range=Get-NormalizedAddressParts '경기도 수원시 권선로 10, 2층~3층 201호' '' '경기도' '수원시'; Assert-Equal $range.Floor '' 'Range floor fails closed'; Assert-Equal $range.Unit '' 'Related unit fails closed'; Assert-True ($range.Warnings -contains 'FLOOR_UNIT_UNCERTAIN') 'Range warning'
$safe=Get-NormalizedAddressParts '경기도 파주시 테스트로 10 지하1층 A-18호' '' '경기도' '파주시'; Assert-Equal $safe.Floor '지하1' 'Basement floor is C-compatible'; Assert-Equal $safe.Unit 'A-18' 'Alphanumeric unit is C-compatible'
$multi=Get-NormalizedAddressParts '경기도 파주시 테스트로 10 101호~102호' '' '경기도' '파주시'; Assert-Equal $multi.Unit '' 'Unit range is not reduced to singleton'; Assert-Equal $multi.AddressParseStatus 'PARTIAL' 'Unit range is partial'; Assert-True ($multi.Warnings -contains 'FLOOR_UNIT_UNCERTAIN') 'Unit range warning'
$dashUnit=Get-NormalizedAddressParts '서울특별시 강남구 도곡로3길 13, 2층 203-2호' '' '서울특별시' '강남구'; Assert-Equal $dashUnit.Unit '' 'Hyphenated numeric unit is not reduced to singleton'; Assert-True ($dashUnit.Warnings -contains 'FLOOR_UNIT_UNCERTAIN') 'Hyphenated numeric unit is warned'
$bareB=Get-NormalizedAddressParts '서울특별시 강남구 도곡로3길 13 B101호' '' '서울특별시' '강남구'; Assert-Equal $bareB.Unit '' 'Bare B101 unit is unsupported'; Assert-Equal $bareB.AddressParseStatus 'PARTIAL' 'Bare B101 unit fails closed'; Assert-True ($bareB.Warnings -contains 'FLOOR_UNIT_UNCERTAIN') 'Bare B101 unit is warned'
$bareA=Get-NormalizedAddressParts '서울특별시 강남구 테스트로 10 A101호' '' '서울특별시' '강남구'; Assert-Equal $bareA.Unit '' 'Bare A101 unit is unsupported'; Assert-Equal $bareA.AddressParseStatus 'PARTIAL' 'Bare A101 unit fails closed'; Assert-True ($bareA.Warnings -contains 'FLOOR_UNIT_UNCERTAIN') 'Bare A101 unit is warned'
$bareC=Get-NormalizedAddressParts '서울특별시 강남구 테스트로 10 C101호' '' '서울특별시' '강남구'; Assert-Equal $bareC.Unit '' 'Bare C101 unit is unsupported'; Assert-Equal $bareC.AddressParseStatus 'PARTIAL' 'Bare C101 unit fails closed'; Assert-True ($bareC.Warnings -contains 'FLOOR_UNIT_UNCERTAIN') 'Bare C101 unit is warned'
$unknown=Get-NormalizedAddressParts '주소 미상' '' '' ''; Assert-Equal $unknown.AddressParseStatus 'UNPARSED' 'Unstructured nonblank address is unparsed'; Assert-True ($unknown.Warnings -contains 'ADDRESS_PARSE_FAILED') 'Unstructured address warning'
$row=[pscustomobject]@{업소명=' 레드폴바버샵 강남신사점 ';시도='서울특별시';시군구='강남구';소재지도로명주소=' 서울특별시 강남구 논현로151길 41, 2층 201호 ';소재지지번주소=' 서울특별시 강남구 신사동 561 '};$business=ConvertTo-NormalizedBusiness $row 2;Assert-PoiContractTypeAndVersion $business 'NormalizedBusiness';Assert-NormalizedBusiness $business;Assert-Equal $business.OriginalName '레드폴바버샵 강남신사점' 'Name is trimmed only'; Assert-Equal $business.OriginalRoadAddress '서울특별시 강남구 논현로151길 41, 2층 201호' 'Road evidence preserved'; Assert-Equal $business.OriginalLotAddress '서울특별시 강남구 신사동 561' 'Lot evidence preserved'; Assert-Equal $business.PreferredAddress $business.OriginalRoadAddress 'Preferred preserves road'; Assert-Equal $business.BaseName '레드폴바버샵 강남신사점' 'Unproven branch stays in source-like B query'; Assert-Equal $business.BranchName '' 'Road-preferred row does not borrow locality evidence from lot address'; Assert-True ($business.NormalizationWarnings -contains 'BRANCH_UNCERTAIN') 'Unproven branch warning'; Assert-True ($business.NormalizationWarnings -is [array]) 'Warnings are arrays'
$again=ConvertTo-NormalizedBusiness $row 2; Assert-Equal ($business|ConvertTo-Json -Depth 8 -Compress) ($again|ConvertTo-Json -Depth 8 -Compress) 'Output is deterministic'
$empty=ConvertTo-NormalizedBusiness ([pscustomobject]@{업소명='';시도='';시군구='';소재지도로명주소='';소재지지번주소=''}) 3; Assert-Equal $empty.AddressParseStatus 'UNPARSED' 'Empty address is unparsed'; Assert-True ($empty.NormalizationWarnings -contains 'ADDRESS_EMPTY') 'Empty address warning'
Write-Host 'Normalization tests passed.'
